<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\Api\V1\{AuthController,AttendanceController,AttendanceStationController,AttendanceIncidentController,LeaveRequestController,PushTokenController};
Route::prefix('v1')->group(function(){Route::post('auth/login',[AuthController::class,'login']);Route::middleware('auth:sanctum')->group(function(){Route::get('auth/me',[AuthController::class,'me']);Route::post('auth/logout',[AuthController::class,'logout']);Route::post('push-tokens',[PushTokenController::class,'store'])->middleware('throttle:30,1');Route::delete('push-tokens',[PushTokenController::class,'destroy'])->middleware('throttle:30,1');Route::get('leave-requests/options',[LeaveRequestController::class,'options']);Route::get('leave-requests',[LeaveRequestController::class,'index']);Route::post('leave-requests',[LeaveRequestController::class,'store']);Route::prefix('attendance')->group(function(){Route::get('status',[AttendanceController::class,'status']);Route::post('clock',[AttendanceController::class,'clock']);Route::get('history',[AttendanceController::class,'history']);Route::get('stations/{workLocation}/token',[AttendanceStationController::class,'token']);Route::get('incidents',[AttendanceIncidentController::class,'index']);Route::post('incidents',[AttendanceIncidentController::class,'store']);});});});
